<?php
 namespace QQWorld\CatalogRule\Test\Unit\Model\Indexer\Product; use QQWorld\Framework\TestFramework\Unit\Helper\ObjectManager; class ProductRuleIndexerTest extends \PHPUnit\Framework\TestCase { protected $indexBuilder; protected $indexer; protected $cacheContextMock; protected function setUp() { $this->indexBuilder = $this->createMock(\QQWorld\CatalogRule\Model\Indexer\IndexBuilder::class); $this->indexer = (new ObjectManager($this))->getObject( \QQWorld\CatalogRule\Model\Indexer\Product\ProductRuleIndexer::class, [ 'indexBuilder' => $this->indexBuilder, ] ); $this->cacheContextMock = $this->createMock(\QQWorld\Framework\Indexer\CacheContext::class); $cacheContextProperty = new \ReflectionProperty( \QQWorld\CatalogRule\Model\Indexer\Product\ProductRuleIndexer::class, 'cacheContext' ); $cacheContextProperty->setAccessible(true); $cacheContextProperty->setValue($this->indexer, $this->cacheContextMock); } public function testDoExecuteList($ids, $idsForIndexer) { $this->indexBuilder->expects($this->once()) ->method('reindexByIds') ->with($idsForIndexer); $this->cacheContextMock->expects($this->once()) ->method('registerEntities') ->with(\QQWorld\Catalog\Model\Product::CACHE_TAG, $ids); $this->indexer->executeList($ids); } public function dataProviderForExecuteList() { return [ [ [1, 2, 3, 2, 3], [1, 2, 3], ], [ [1, 2, 3], [1, 2, 3], ], ]; } public function testDoExecuteRow() { $id = 5; $this->indexBuilder->expects($this->once())->method('reindexById')->with($id); $this->indexer->executeRow($id); } } 